//! `help.open`: the documentation page (`docs/penumbra.html`, generated by `cargo xtask docs`)
//! in the default browser, at the entry of a node kind or command. The `?` in a node's header
//! and in the param panel call it.
//!
//! On Windows, opening `file:///...html#entry` through the file association loses the
//! `#entry`: the shell hands the browser a path, and a path has no fragment. So the browser is
//! given a small page of our own, written to the temp directory, that replaces itself with the
//! documentation at the entry. Runs that must not open windows (headless, tests) only answer
//! where the page is.

use std::path::{Path, PathBuf};

use serde_json::{Value as Json, json};

/// The page's place below a directory holding the documentation.
const PAGE: &str = "docs/penumbra.html";

/// How many directories above the executable's own the documentation is looked for: the
/// release zip has `docs` beside the exe, a checkout four levels up (`target/<dir>/debug/deps`
/// for tests).
const SEARCH_DEPTH: usize = 5;

/// The documentation page beside the executable or a few levels above it; the checkout's when
/// this build runs from its own tree.
pub fn find_page() -> Result<PathBuf, String> {
    let mut looked = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        for dir in exe.ancestors().skip(1).take(SEARCH_DEPTH + 1) {
            let page = dir.join("docs").join("penumbra.html");
            if page.is_file() {
                return Ok(page);
            }
            looked.push(dir.display().to_string());
        }
    }
    let checkout = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs/penumbra.html");
    if checkout.is_file() {
        return Ok(std::path::absolute(&checkout).unwrap_or(checkout));
    }
    Err(format!(
        "the documentation ({PAGE}) is not beside the program or above it (looked in {}); \
         a checkout writes it with `cargo xtask docs`",
        if looked.is_empty() { "no directory".into() } else { looked.join(", ") }
    ))
}

/// A `file://` URL for an absolute path, with what a URL cannot hold percent-encoded.
pub fn file_url(path: &Path) -> String {
    let text = path.to_string_lossy().replace('\\', "/");
    // Windows' verbatim prefix, from canonicalised paths.
    let text = text.strip_prefix("//?/UNC/").map(|t| format!("//{t}")).unwrap_or(text);
    let text = text.strip_prefix("//?/").map(str::to_string).unwrap_or(text);
    let (host, rest) = match text.strip_prefix("//") {
        Some(unc) => unc.split_once('/').map_or((unc, ""), |(h, r)| (h, r)),
        None => ("", text.trim_start_matches('/')),
    };
    let mut url = format!("file://{}/", encode(host, false));
    url.push_str(&encode(rest, true));
    url
}

/// Percent-encodes `text` except unreserved characters (and `/` and `:` when `path`).
fn encode(text: &str, path: bool) -> String {
    let mut out = String::new();
    for b in text.bytes() {
        let keep = b.is_ascii_alphanumeric()
            || matches!(b, b'-' | b'.' | b'_' | b'~')
            || (path && matches!(b, b'/' | b':'));
        if keep {
            out.push(char::from(b));
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

/// Whether the page has an element with this id (an entry or a heading).
fn has_anchor(html: &str, id: &str) -> bool {
    let escaped = id.replace('&', "&amp;").replace('"', "&quot;").replace('<', "&lt;").replace('>', "&gt;");
    html.contains(&format!(" id=\"{escaped}\""))
}

/// The small page that sends the browser on to `url`, fragment included.
fn redirect_page(url: &str) -> String {
    // A JSON string is a JavaScript string; `<\/` keeps a `</script>` in the URL from ending the
    // script.
    let js = serde_json::to_string(url).unwrap_or_else(|_| "\"\"".into()).replace("</", "<\\/");
    let attr = url.replace('&', "&amp;").replace('"', "&quot;").replace('<', "&lt;");
    format!(
        "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><title>penumbra documentation</title>\n\
         <script>location.replace({js});</script></head>\n\
         <body><p><a href=\"{attr}\">penumbra documentation</a></p></body></html>\n"
    )
}

/// Opens `file` with the program the system has for it (the default browser for `.html`),
/// waited for on a thread so it leaves no zombie.
fn open_with_system(file: &Path) -> Result<(), String> {
    let program = if cfg!(windows) {
        "explorer"
    } else if cfg!(target_os = "macos") {
        "open"
    } else {
        "xdg-open"
    };
    let mut child = std::process::Command::new(program)
        .arg(file)
        .spawn()
        .map_err(|e| format!("cannot start {program}: {e}"))?;
    std::thread::Builder::new()
        .name("browser".into())
        .spawn(move || {
            child.wait().ok();
        })
        .map(|_| ())
        .map_err(|e| format!("cannot wait for {program}: {e}"))
}

/// The documentation at `entry` (a node kind, a command, a guide or a heading id; the top
/// without one): where it is, and in the browser when `browser`. An error when the page is
/// missing or has no such entry.
pub fn open(entry: Option<&str>, browser: bool) -> Result<Json, String> {
    let page = find_page()?;
    let entry = entry.map(str::trim).filter(|e| !e.is_empty());
    if let Some(id) = entry {
        let html =
            std::fs::read_to_string(&page).map_err(|e| format!("cannot read {}: {e}", page.display()))?;
        if !has_anchor(&html, id) {
            return Err(format!(
                "the documentation has no entry `{id}`; give a node kind (`tex.noise`), a command (`node.set`) or a guide (`scanning`)"
            ));
        }
    }
    let mut url = file_url(&page);
    if let Some(id) = entry {
        url.push('#');
        url.push_str(&encode(id, false));
    }
    let mut opened = Json::Null;
    if browser {
        let dir = std::env::temp_dir().join("penumbra");
        std::fs::create_dir_all(&dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
        let redirect = dir.join("help.html");
        std::fs::write(&redirect, redirect_page(&url))
            .map_err(|e| format!("cannot write {}: {e}", redirect.display()))?;
        open_with_system(&redirect)?;
        opened = json!(redirect.display().to_string());
    }
    Ok(json!({
        "file": page.display().to_string(),
        "url": url,
        "entry": entry,
        "opened": !opened.is_null(),
        "redirect": opened,
    }))
}

/// The `help.open` command: `{kind?, open?}`; `open: false` only answers where the page is.
pub fn command(params: &Json, browser: bool) -> Result<Json, String> {
    let kind = match params.get("kind") {
        None | Some(Json::Null) => None,
        Some(Json::String(s)) => Some(s.as_str()),
        Some(_) => return Err("`kind` must be a text: a node kind, a command or a guide".into()),
    };
    let wanted = match params.get("open") {
        None | Some(Json::Null) => true,
        Some(Json::Bool(b)) => *b,
        Some(_) => return Err("`open` must be true or false".into()),
    };
    open(kind, browser && wanted)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn urls_encode_what_a_url_cannot_hold() {
        assert_eq!(
            file_url(Path::new(r"C:\Program Files\pen umbra\docs\penumbra.html")),
            "file:///C:/Program%20Files/pen%20umbra/docs/penumbra.html"
        );
        assert_eq!(file_url(Path::new(r"\\?\E:\a#b\c.html")), "file:///E:/a%23b/c.html");
        assert_eq!(file_url(Path::new(r"\\server\share\d.html")), "file://server/share/d.html");
        assert_eq!(file_url(Path::new("/home/u/ä.html")), "file:///home/u/%C3%A4.html");
    }

    #[test]
    fn the_redirect_keeps_the_fragment_and_cannot_end_its_script() {
        let page = redirect_page("file:///E:/docs/penumbra.html#tex.shapes");
        assert!(page.contains(r#"location.replace("file:///E:/docs/penumbra.html#tex.shapes")"#), "{page}");
        let page = redirect_page("file:///x</script><b>.html#a");
        assert!(!page.contains("</script><b>"), "{page}");
    }

    #[test]
    fn anchors_are_found_by_id_only() {
        let html = r#"<details class="entry" id="tex.noise"><p>tex.blur</p>"#;
        assert!(has_anchor(html, "tex.noise"));
        assert!(!has_anchor(html, "tex.blur"));
        assert!(!has_anchor(html, "tex"));
    }

    #[test]
    fn the_command_finds_the_page_and_opens_nothing_headless() {
        let reply = command(&json!({"kind": "tex.noise"}), false).unwrap();
        assert_eq!(reply["opened"], false);
        assert!(reply["url"].as_str().unwrap().ends_with("/docs/penumbra.html#tex.noise"), "{reply}");
        assert!(Path::new(reply["file"].as_str().unwrap()).is_file());
        let top = command(&json!({}), false).unwrap();
        assert!(top["url"].as_str().unwrap().ends_with("/docs/penumbra.html"), "{top}");
        let commands = command(&json!({"kind": "help.open"}), false).unwrap();
        assert_eq!(commands["entry"], "help.open");
        let missing = command(&json!({"kind": "tex.nothing"}), false).unwrap_err();
        assert!(missing.contains("no entry `tex.nothing`"), "{missing}");
        assert!(command(&json!({"kind": 3}), false).is_err());
        assert!(command(&json!({"open": "yes"}), false).is_err());
    }
}
